function verticalTraversal(root) {
  const entries = [];

  const visit = (node, row, col) => {
    if (node === null) {
      return;
    }
    entries.push([col, row, node.val]);
    visit(node.left, row + 1, col - 1);
    visit(node.right, row + 1, col + 1);
  };

  visit(root, 0, 0);
  entries.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);

  const result = [];
  let lastCol = null;
  for (const [col, , val] of entries) {
    if (col !== lastCol) {
      result.push([]);
      lastCol = col;
    }
    result[result.length - 1].push(val);
  }
  return result;
}

