function verticalTraversal(root) {
  // Walk level by level; within a level, sort each column's values before appending them.
  const columns = new Map();
  let level = [[root, 0]];
  while (level.length) {
    const here = new Map();
    const nextLevel = [];
    for (const [node, col] of level) {
      if (!here.has(col)) here.set(col, []);
      here.get(col).push(node.val);
      if (node.left) nextLevel.push([node.left, col - 1]);
      if (node.right) nextLevel.push([node.right, col + 1]);
    }
    for (const [col, values] of here) {
      if (!columns.has(col)) columns.set(col, []);
      columns.get(col).push(...values.sort((a, b) => a - b));
    }
    level = nextLevel;
  }
  const keys = [...columns.keys()].sort((a, b) => a - b);
  return keys.map(k => columns.get(k));
}

