function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 14);
  // Small values make equal values at shared positions common.
  const top = size === 'large' ? (rand() < 0.5 ? 1000 : 20) : (rand() < 0.5 ? 9 : 1000);
  const value = () => Math.floor(rand() * (top + 1));
  // Shape: random free slots, or mostly one chain to get deep columns.
  const chainy = rand() < 0.25;
  const nodes = [{ val: value(), left: null, right: null }];
  const slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = chainy ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: value(), left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
